// capture is what run printed.
func capture(t *testing.T, run func()) string {
	read, write, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	stdout := os.Stdout
	os.Stdout = write
	run()
	os.Stdout = stdout
	write.Close()

	var printed bytes.Buffer
	if _, err := io.Copy(&printed, read); err != nil {
		t.Fatal(err)
	}
	return printed.String()
}
